"""Conservative native IRQ call graph; reports unresolved edges, never assumes them safe."""
from disasm import *
import re,collections
pages=(15,31,45,0)
rows={};functions={};issues=[]
def ins(pc):
    page=pages[pc>>14];off=0x4800+(page<<10)+(pc&0x3fff)
    i=ctx.disassemble(data[off:off+12],base_address=pc,max_instructions=1).instructions[0]
    row=dict(pc=pc,page=page,file=off,bytes=data[off:off+i.length].hex(),op=i.mnem,body=i.body,length=i.length)
    rows[pc]=row
    return row
def target(body):return int(body.split()[-1],16)&65535
tables={0x21db:(0x21de,4,9),0x2a59:(0x2a5c,4,11),0x2ab0:(0x2ab2,4,6),
    0x4dca:(0x4dcc,2,8),0x5ef8:(0x5efa,2,4),0x6cf8:(0x6cfa,2,7),
    0x800c:(0x800e,2,8),0x84d3:(0x84d6,2,10),0x5fad:(0x5fb0,4,32)}
pending=[0x4000,0x213a,0xcd1f,0xcbcf]
while pending:
    root=pending.pop()
    if root in functions:continue
    todo=[(root,0)];seen=set();exits=set();calls={};jumps=[];high=0
    while todo:
        pc,depth=todo.pop()
        if (pc,depth) in seen:continue
        seen.add((pc,depth))
        if len(seen)>100000 or abs(depth)>1024:
            issues.append(dict(root=root,pc=pc,reason='unbalanced loop or excessive graph'));break
        row=ins(pc);op=row['op'];body=row['body'];nextpc=pc+row['length']
        depth+={'PUSH':2,'POP':-2,'PUSHA':4,'POPA':-4,'PUSHF':2,'POPF':-2}.get(op,0)
        high=max(high,depth)
        if op=='RET':exits.add(depth)
        elif op in ('LCALL','SCALL'):
            dest=target(body);calls.setdefault(dest,set()).add(depth+2);pending.append(dest);todo.append((nextpc,depth))
        elif op in ('LJMP','SJMP'):todo.append((target(body),depth))
        elif op=='BR':
            jumps.append(row)
            if pc in tables:
                start,stride,count=tables[pc]
                todo.extend((start+n*stride,depth) for n in range(count))
            else:issues.append(dict(root=root,pc=pc,reason='unresolved indirect branch',instruction=row))
        elif op.startswith('J') or op in ('DJNZ','DJNZW'):todo.extend([(target(body),depth),(nextpc,depth)])
        else:
            if op in ('ST','STB','POP') and re.search(r'0x10[0246],',body) and pc not in (0x6965,0x696f):
                issues.append(dict(root=root,pc=pc,reason='fetch selector mutation',instruction=row))
            todo.append((nextpc,depth))
    functions[root]=dict(root=root,local_high=high,return_depths=sorted(exits),instructions=len(seen),
        calls={str(k):sorted(v) for k,v in calls.items()},indirect=jumps)
def bound(root,trail=()):
    if root in trail:raise ValueError(('recursive call graph',trail,root))
    f=functions[root];best=(f['local_high'],[root])
    for child,depths in f['calls'].items():
        value,path=bound(int(child),trail+(root,))
        candidate=(max(depths)+value,[root]+path)
        if candidate[0]>best[0]:best=candidate
    return best
bounds={}
for root in (0x4000,0x213a,0xcd1f,0xcbcf):
    try:bounds[hex(root)]=bound(root)
    except ValueError as exc:issues.append(str(exc))
report=dict(roots=[0x4000,0x213a,0xcd1f,0xcbcf],pages=pages,bounds=bounds,functions=list(functions.values()),
    issues=issues,decoded=list(rows.values()),resolved_graph_under_assumptions=not issues,
    complete_safety_gate=False,
    assumptions=['Fetch pages 000F/001F/002D/0000 established by timer ISR; 6965/696F temporarily reassert/restore 002D.',
        'Native parser/envelope states restricted to their declared jump-table domains; mutable state writer invariants not universally proved.',
        'Timer prologue14 bytes plus control routine36 plus non-nesting wave ISR12 gives conditional62-byte IRQ bound; MIDI IRQ6 is smaller.',
        'Caller masks must exclude active FDC/SCSI owners; physical arbitration and complete UI caller/callee bound are separate.',
        'MIDI parser213A drains a live ring while arrivals remain enabled; graph stack closure is not a service-time bound.'])
(P/'irq-graph.json').write_text(json.dumps(report,indent=2)+'\n')
print(json.dumps(dict(functions=len(functions),instructions=len(rows),issues=issues,bounds=bounds,
    nonzero_returns=[(hex(k),v['return_depths']) for k,v in functions.items() if v['return_depths']!=[0]]),indent=2))

